/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3.12 -c 'from solution import TTLCache
def check(name, fn):
    try: fn()
    except Exception as e: print(f\"FAIL {name}: {type(e).__name__}: {e}\")
    else: print(f\"PASS {name}\")
def capacity():
    for v in (True, False, 0, -1, 1.5, \"2\", None):
        try: TTLCache(v, lambda:0)
        except ValueError: continue
        raise AssertionError(f\"accepted {v"'!r}")
def expiry():
    t=[0]; c=TTLCache(2,lambda:t[0]); c.set("a",1,1); t[0]=1
    assert c.get("a","missing")=="missing", "survives exact deadline"
def cleanup():
    t=[0]; c=TTLCache(2,lambda:t[0]); c.set("a",1,1); t[0]=2
    assert len(c)==0, "len includes expired entry"
def values():
    for v in (None,0,False,""):
        c=TTLCache(1,lambda:0); c.set("a",v,1)
        assert c.get("a","missing") is v, f"changed {v!r}"
def recency():
    c=TTLCache(2,lambda:0); c.set("a",1,10); c.set("b",2,10); c.get("a"); c.set("c",3,10)
    assert c.get("a")==1 and c.get("b") is None, "wrong LRU eviction"
def replace():
    c=TTLCache(2,lambda:0); c.set("a",1,10); c.set("b",2,10); c.set("b",3,10)
    assert c.get("a")==1, "replacement evicts another key"
def zero():
    c=TTLCache(2,lambda:0); c.set("a",1,0)
    assert len(c)==0, "stores zero ttl entry"
def invalid():
    c=TTLCache(1,lambda:0); c.set("a",1,10)
    try: c.set("b",2,"bad")
    except ValueError: pass
    except Exception as e: raise AssertionError(f"raises {type(e).__name__}; remaining entries {c.items!r}")
    else: raise AssertionError("accepted invalid ttl")
def eviction():
    t=[0]; c=TTLCache(2,lambda:t[0]); c.set("live",1,10); c.set("expired",2,1); t[0]=2; c.set("new",3,10)
    assert c.get("live")==1, "evicts live entry before expired entry"
for name,fn in (("capacity",capacity),("exact expiry",expiry),("len cleanup",cleanup),("stored values",values),("LRU",recency),("replacement",replace),("zero ttl",zero),("invalid ttl atomicity",invalid),("expiry before eviction",eviction)):
    check(name,fn)
for ttl in (True,False,-1,float("nan"),float("inf"),float("-inf")):
    c=TTLCache(2,lambda:0)
    try: c.set("x",1,ttl)
    except ValueError: print(f"PASS rejects ttl={ttl!r}")
    else: print(f"FAIL accepts ttl={ttl!r}")
